:root{--bg:#050505;--card:#121212;--line:#262626;--gold:#bfa066;--tx:#eee;--mu:#9a9a9a;--r:2px}
*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{background:var(--bg);color:var(--tx);font:500 14px/1.6 "Montserrat",sans-serif;-webkit-text-size-adjust:100%;min-height:100vh;min-height:100dvh;display:flex;flex-direction:column}
main{flex:1 0 auto;width:100%}
header,footer{flex:none}
h1,h2,h3,h4,b,strong,button,.btn,.logo,label{font-weight:600}
a{color:inherit;text-decoration:none}
button,input,select,textarea{font:inherit;color:inherit}
button{cursor:pointer}
:focus-visible{outline:2px solid var(--gold);outline-offset:2px}
.wrap{max-width:1040px;margin:0 auto;padding:0 20px}
.mu{color:var(--mu)}.gold{color:var(--gold)}.sm{font-size:12px}
header{position:sticky;top:0;z-index:20;background:var(--bg);border-bottom:1px solid var(--line)}
header .wrap{display:flex;align-items:center;justify-content:space-between;height:56px;max-width:none;padding:0 24px}
.logo{font-size:18px;letter-spacing:.5px}.logo i{font-style:normal;color:var(--gold)}
.hr{display:flex;gap:8px}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:6px;padding:11px 18px;border:1px solid var(--gold);background:var(--gold);color:#111;border-radius:var(--r);font-size:13px;transition:.2s}
.btn:hover{filter:brightness(1.1)}
.btn.o{background:transparent;color:var(--gold)}
.btn.o:hover{background:#bfa06622}
.btn.k{background:var(--bg);color:var(--tx);border-color:var(--line)}
.btn.w{width:100%}
.btn.s{padding:8px 14px;font-size:12px}
.lnk{color:var(--gold);font-size:13px;background:none;border:0;display:inline-block;padding:0}
.lnk:hover{text-decoration:underline}
.eb{color:var(--gold);font-size:11px;letter-spacing:1px;margin-bottom:8px}
h1{font-size:clamp(28px,5vw,44px);line-height:1.15;margin-bottom:12px}
h2{font-size:clamp(20px,3vw,26px);margin-bottom:12px}
h3{font-size:16px;margin-bottom:6px}
.view{display:none;padding:40px 0 64px}
.view.on{display:block}
.lead{color:var(--mu);margin-bottom:24px;max-width:560px}
.card{background:var(--card);border:1px solid var(--line);padding:22px;border-radius:var(--r)}
.card p{color:var(--mu);font-size:13px}
.g2,.g3,.g4{display:grid;gap:12px}
.g2{grid-template-columns:repeat(2,1fr)}.g3{grid-template-columns:repeat(3,1fr)}.g4{grid-template-columns:repeat(4,1fr)}
.split{display:grid;grid-template-columns:1.4fr 1fr;gap:16px;align-items:start}
.mt{margin-top:32px}.mt2{margin-top:16px}
.num{color:var(--gold);font-size:12px;display:block;margin-bottom:12px}
.note{color:var(--mu);font-size:12px;margin:16px 0}
.steps{display:flex;gap:18px;font-size:12px;color:var(--mu);margin-bottom:24px;flex-wrap:wrap}
.steps .on{color:var(--gold)}
/* stone textures */
.img{width:100%;aspect-ratio:3/2;border-radius:var(--r);position:relative;overflow:hidden;background-size:cover}
.trav{background:#1a1a1a center/cover no-repeat url("data:image/jpeg;base64,")}
.cal{background:#1a1a1a center/cover no-repeat url("data:image/jpeg;base64,")}
.grey{background:#1a1a1a center/cover no-repeat url("data:image/jpeg;base64,")}
.verde{background:#1a1a1a center/cover no-repeat url("data:image/jpeg;base64,")}
.white{background:#1a1a1a center/cover no-repeat url("data:image/jpeg;base64,")}
.carr{background:#1a1a1a center/cover no-repeat url("data:image/jpeg;base64,")}
.nero{background:#1a1a1a center/cover no-repeat url("data:image/jpeg;base64,")}
.emp{background:#1a1a1a center/cover no-repeat url("data:image/jpeg;base64,")}
.kit{background:#1a1a1a center/cover no-repeat url("data:image/jpeg;base64,")}
.room{background:#1a1a1a center/cover no-repeat url("data:image/jpeg;base64,")}
.dine{background:#1a1a1a center/cover no-repeat url("data:image/jpeg;base64,")}
.rdine{background:#1a1a1a center/cover no-repeat url("data:image/jpeg;base64,")}
.lounge{background:#1a1a1a center/cover no-repeat url("data:image/jpeg;base64,")}
.team{background:#1a1a1a center/cover no-repeat url("data:image/jpeg;base64,")}
.b1{background:#fff center/contain no-repeat url("data:image/jpeg;base64,")}
.b2{background:#fff center/contain no-repeat url("data:image/jpeg;base64,")}
.b3{background:#fff center/contain no-repeat url("data:image/jpeg;base64,")}
.b4{background:#fff center/contain no-repeat url("data:image/jpeg;base64,")}
.inq{grid-template-columns:2fr 1fr;align-items:stretch}
#inqList{display:grid;gap:12px}
#inqList .card{height:100%}
.tag{position:absolute;top:8px;left:8px;background:#000;color:var(--tx);font-size:11px;padding:3px 8px}
.tag.r{left:auto;right:8px}
.heart{position:absolute;top:8px;right:8px;background:#000;border:0;width:26px;height:26px;color:var(--tx)}
.heart.on{color:var(--gold)}
/* home */
.hero{display:grid;grid-template-columns:1fr 1fr;gap:32px;align-items:center}
.hero .img{aspect-ratio:384/312}
.cap{position:absolute;left:12px;bottom:13px;background:#000;padding:10px 14px;font-size:11px;line-height:1.5}

.drop{cursor:pointer;margin:14px 0;transition:.2s}
.drop.hot{color:var(--gold)}
.cta{display:flex;gap:8px;flex-wrap:wrap}
.trust{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;background:var(--card);padding:16px 18px;margin:32px 0;font-size:12px;color:var(--mu)}
.chip{cursor:pointer;display:block}
.chip .img{aspect-ratio:2.8/1;margin-bottom:6px}
.chip span{font-size:12px}
/* review / results */
.prev img{width:100%;border-radius:var(--r);display:block}
.res .m{font-size:12px;color:var(--mu);margin:6px 0 12px}
.res .row{display:flex;gap:8px;flex-wrap:wrap}
.btn.sel{outline:2px solid #fff}
.bar{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}
input,select,textarea{font-weight:500;width:100%;background:#0a0a0a;border:1px solid var(--line);padding:11px 12px;border-radius:var(--r);margin-top:6px}
textarea{min-height:90px;resize:vertical}
label{font-size:12px;display:block}
.fg{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:14px}
.fg .full{grid-column:1/-1}
.err{border-color:#c0584f}
.errm{color:#e07a70;font-size:11px;margin-top:4px;display:none}
.kv{display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid var(--line);font-size:13px}
.kv span:first-child{color:var(--mu)}
.thumb{width:64px;height:64px;border-radius:var(--r);flex:none}
.mat{display:flex;gap:12px;align-items:center;margin-bottom:12px}
.chk{display:flex;gap:8px;align-items:flex-start;font-size:12px;color:var(--mu);margin:14px 0}
.chk input{width:auto;margin:3px 0 0}
.ok{text-align:center;max-width:560px;margin:0 auto}
.ok .card{text-align:left;margin:24px 0}
.tick{width:64px;height:64px;background:var(--card);color:var(--gold);display:grid;place-items:center;margin:0 auto 20px;font-size:24px}
/* faq */
.faq{border-bottom:1px solid var(--line)}
.faq button{width:100%;background:none;border:0;text-align:left;padding:16px 0;display:flex;justify-content:space-between;gap:12px}
.faq p{display:none;color:var(--mu);padding:0 0 16px;font-size:13px}
.faq.on p{display:block}.faq.on button i{transform:rotate(45deg)}
.faq i{font-style:normal;color:var(--gold);transition:.2s}
.tabs{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:16px}
.tabs button{background:none;border:1px solid var(--line);padding:6px 14px;font-size:12px;color:var(--mu);border-radius:var(--r)}
.tabs button.on{border-color:var(--gold);color:var(--gold)}
.stat b{font-size:28px;color:var(--gold);display:block}
/* drawer + toast + footer */
.drawer{position:fixed;inset:0;z-index:40;background:#000c;display:none}
.drawer.on{display:block}
.drawer nav{position:absolute;right:0;top:0;bottom:0;width:min(300px,85%);background:var(--card);padding:24px;display:flex;flex-direction:column;gap:4px;overflow:auto}
.drawer a{padding:12px 0;border-bottom:1px solid var(--line);font-size:14px}
.drawer a:hover{color:var(--gold)}
.toast{position:fixed;left:50%;bottom:24px;transform:translate(-50%,40px);background:var(--gold);color:#111;padding:10px 18px;border-radius:var(--r);opacity:0;transition:.3s;z-index:50;font-size:13px;pointer-events:none}
.toast.on{opacity:1;transform:translate(-50%,0)}
footer{border-top:1px solid var(--line);padding:22px 24px;display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;font-size:12px;color:var(--mu)}
footer div{display:flex;gap:18px}
.split.eq{grid-template-columns:1fr 1fr}.split.w2{grid-template-columns:2fr 1fr}.split.s24{grid-template-columns:240px 1fr}.split.f18{grid-template-columns:1.8fr 1fr}
.flt{display:flex;flex-wrap:wrap;margin-bottom:16px}
.flt button{background:none;border:0;color:var(--gold);font-size:12px;padding:0}
.flt button:not(:last-child)::after{content:" · ";color:var(--mu);white-space:pre}
.flt button.on{text-decoration:underline}
.lw{color:var(--tx);font-size:12px}
.btn.act{outline:2px solid #fff}
@media(max-width:760px){
.wrap{padding:0 16px}header .wrap{padding:0 16px}
.hero,.split,.g2,.g3{grid-template-columns:1fr!important}
.g4{grid-template-columns:repeat(2,1fr)}
.fg{grid-template-columns:1fr}
.view{padding:28px 0 48px}
.hr .btn{padding:9px 12px;font-size:12px}
.trust{flex-direction:column}
.bar .btn{width:100%}
.cta .btn{flex:1}
}
@media(max-width:400px){.hr .btn{padding:8px 9px;font-size:11px}.logo{font-size:15px}.hr{gap:6px}}
@media(prefers-reduced-motion:reduce){*{transition:none!important;scroll-behavior:auto!important}}
